<script setup lang="ts">
import {computed,ref} from 'vue'
import {listVaultItems,saveVaultItem} from '../services/vault'
import {vaultImportIdentity,type VaultImportItem} from '../services/vaultImport'
import {parseVaultMarkdown} from '../services/vaultMarkdownImport'
import {vaultAreaUid,type VaultProject} from '../services/vaultAttribution'
const props=defineProps<{ownerId:string;vaultKey:CryptoKey;hideTrigger?:boolean;defaultAreaUid?:string|null;projects?:VaultProject[]}>(),emit=defineEmits<{changed:[]}>()
const importAreaUid=ref<string|null>(null)
const open=ref(false),busy=ref(false),items=ref<VaultImportItem[]>([]),errors=ref<Array<{row:number;message:string}>>([]),message=ref(''),fileCount=ref(0)
const typeCounts=computed(()=>Object.entries(items.value.reduce<Record<string,number>>((result,item)=>{result[item.credentialType||'login']=(result[item.credentialType||'login']||0)+1;return result},{})).map(([type,count])=>`${type} ${count}`).join(' · '))
function reset(){items.value=[];errors.value=[];message.value='';fileCount.value=0}
function openDialog(){reset();importAreaUid.value=props.defaultAreaUid||null;open.value=true}
defineExpose({open:openDialog})
async function choose(event:Event){const input=event.target as HTMLInputElement,files=[...(input.files||[])];reset();fileCount.value=files.length;busy.value=true;try{for(const file of files){const result=parseVaultMarkdown(await file.text(),file.name);items.value.push(...result.items.map(item=>({...item,areaUid:importAreaUid.value,projectUid:null})));errors.value.push(...result.errors)}if(!items.value.length)message.value='没有识别到可安全导入的凭据'}catch(source){message.value=source instanceof Error?source.message:'Markdown 解析失败'}finally{busy.value=false;input.value=''}}
async function execute(){if(!items.value.length)return;busy.value=true;message.value='';try{const existing=new Set((await listVaultItems(props.ownerId,props.vaultKey)).map(item=>vaultImportIdentity({...item,areaUid:vaultAreaUid(item,props.projects||[])})));let imported=0,skipped=0;for(const item of items.value){const identity=vaultImportIdentity(item);if(existing.has(identity)){skipped++;continue}await saveVaultItem(props.ownerId,props.vaultKey,{...item,password:item.password||''});existing.add(identity);imported++}message.value=`已加密导入 ${imported} 条${skipped?`，跳过重复 ${skipped} 条`:''}`;items.value=[];emit('changed')}catch(source){message.value=source instanceof Error?source.message:'导入失败'}finally{busy.value=false}}
</script>
<template><slot v-if="!hideTrigger" :open="openDialog"><button class="markdown-import-entry" @click="openDialog">导入 Markdown 凭据</button></slot><Teleport to="body"><div v-if="open" class="markdown-mask" @click.self="!busy&&(open=false)"><section class="markdown-dialog"><header><div><small>LOCAL ONLY</small><h2>本机整理 Markdown 凭据</h2><p>只使用本地规则分析，文件内容不会发送给服务器或 AI。</p></div><button :disabled="busy" @click="open=false">×</button></header><label class="picker">选择 Markdown 文件<input type="file" accept=".md,text/markdown,text/plain" multiple :disabled="busy" @change="choose"></label><div v-if="fileCount" class="summary"><b>{{fileCount}} 个文件</b><span>识别 {{items.length}} 条</span><span>{{typeCounts||'—'}}</span><span>{{errors.length}} 项待确认</span></div><div v-if="items.length" class="preview"><article v-for="(item,index) in items.slice(0,20)" :key="`${item.title}-${index}`"><span><b>{{item.title}}</b><small>{{item.credentialType}} · {{item.username||item.host||item.url||item.category}}</small></span><em>{{item.password?'含密码':item.privateKey?'含私钥':item.licenseKey?'含许可证':item.totpSecret?'含 TOTP':'含恢复码'}}</em></article></div><div v-if="errors.length" class="errors"><b>未自动导入</b><span v-for="(value,index) in errors.slice(0,12)" :key="index">{{value.message}}</span></div><p v-if="message" class="message">{{message}}</p><footer><button :disabled="busy" @click="open=false">关闭</button><button class="primary" :disabled="busy||!items.length" @click="execute">{{busy?'处理中…':`确认加密导入 ${items.length} 条`}}</button></footer></section></div></Teleport></template>
<style scoped>
.markdown-import-entry{padding:6px 9px;border:1px solid currentColor;border-radius:6px;background:transparent;color:inherit;font-size:9px;cursor:pointer}.markdown-mask{position:fixed;z-index:2100;inset:0;display:grid;place-items:center;padding:20px;background:#13241b66}.markdown-dialog{display:grid;width:min(700px,calc(100vw - 40px));max-height:calc(100vh - 50px);overflow:auto;border-radius:14px;background:#fff;box-shadow:0 30px 80px #102b1d50}.markdown-dialog>header{display:flex;justify-content:space-between;padding:20px 22px;border-bottom:1px solid var(--pc-border)}h2,p{margin:0}header small{color:var(--pc-primary);font-size:8px}header h2{margin:4px 0;font-size:17px}header p{color:var(--pc-muted);font-size:9px}header>button{border:0;background:transparent;font-size:20px}.picker{margin:16px 22px;padding:10px 13px;border-radius:8px;background:var(--pc-primary);color:#fff;font-size:9px;cursor:pointer}.picker input{display:none}.summary{display:flex;gap:14px;margin:0 22px 12px;padding:10px;border:1px solid var(--pc-border);border-radius:8px;font-size:8px}.preview,.errors{display:grid;margin:0 22px 12px;border:1px solid var(--pc-border);border-radius:8px}.preview article{display:flex;justify-content:space-between;padding:8px 10px;border-top:1px solid #edf1ee}.preview article:first-child{border:0}.preview span{display:grid}.preview small,.preview em{color:var(--pc-muted);font-size:7px}.preview em{color:var(--pc-primary);font-style:normal}.errors{gap:4px;padding:10px;color:#965050;font-size:8px}.message{margin:0 22px 12px;padding:9px;background:#f1f8f4;color:#356247;font-size:8px}.markdown-dialog footer{display:flex;justify-content:flex-end;gap:8px;padding:14px 22px;border-top:1px solid var(--pc-border)}footer button{padding:8px 11px;border:1px solid var(--pc-border);border-radius:7px;background:#fff}.primary{border-color:var(--pc-primary)!important;background:var(--pc-primary)!important;color:#fff}
</style>
